</main></div></div><?php if(user()['role']==='content_manager'):?><div class="modal fade" id="aiDraftModal" tabindex="-1"><div class="modal-dialog modal-lg modal-dialog-scrollable"><form class="modal-content" id="aiDraftForm"><div class="modal-header"><div><h2 class="modal-title fs-5"><i class="bi bi-stars text-info"></i> Generate with AI</h2><small class="text-muted">AI creates a draft only. Review it before saving.</small></div><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="kind" id="aiKind"><input type="hidden" name="target_id" id="aiTargetId"><div id="aiTargetWrap" class="mb-3 d-none"><label class="form-label">Career content</label><select class="form-select" id="aiTargetSelect"></select></div><div id="aiCareerContext" class="alert alert-info py-2 d-none"><i class="bi bi-briefcase me-1"></i> Generating specifically for <strong id="aiCareerName"></strong></div><div id="aiInterestWrap" class="mb-3 d-none"><label class="form-label">RIASEC type</label><select class="form-select" name="interest_type" id="aiInterestType"><?php foreach(['realistic','investigative','artistic','social','enterprising','conventional'] as $type):?><option value="<?=$type?>"><?=ucfirst($type)?></option><?php endforeach?></select></div><div class="row g-3"><div class="col-md-8"><label class="form-label">Topic</label><input class="form-control" name="topic" required maxlength="300" placeholder="e.g. handling a difficult client professionally"></div><div class="col-md-4"><label class="form-label">Difficulty</label><select class="form-select" name="difficulty"><option>beginner</option><option>intermediate</option><option>advanced</option></select></div></div><div id="aiDraftReview" class="d-none mt-4"><label class="form-label fw-semibold">Review and edit the generated draft</label><textarea class="form-control font-monospace" id="aiDraftJson" name="draft_json" rows="16"></textarea><div class="form-text">Nothing is added until you select “Save reviewed draft.”</div></div></div><div class="modal-footer"><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">Cancel</button><button class="btn btn-outline-primary" id="aiGenerateButton"><i class="bi bi-stars"></i> Generate draft</button><button type="button" class="btn btn-primary d-none" id="aiSaveButton">Save reviewed draft</button></div></form></div></div><?php endif?><div class="modal fade" id="contentEditorModal" tabindex="-1"><div class="modal-dialog modal-lg modal-dialog-scrollable"><div class="modal-content"><div class="modal-header"><h2 class="modal-title fs-5">Manage content</h2><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body" id="contentEditorBody"><div class="text-center py-5"><div class="spinner-border text-primary"></div></div></div></div></div></div><div class="toast-container position-fixed bottom-0 end-0 p-3" id="toastArea"></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.3/dist/chart.umd.min.js"></script><script src="<?=url('assets/js/app.js')?>"></script><script>
document.getElementById('adminGlobalSearch')?.addEventListener('input',function(){const q=this.value.toLowerCase();document.querySelectorAll('tbody tr').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(q))});
document.getElementById('sidebarCollapse')?.addEventListener('click',function(){const collapsed=document.documentElement.classList.toggle('sidebar-is-collapsed');localStorage.setItem('careerSimSidebar',collapsed?'collapsed':'expanded');this.setAttribute('aria-label',collapsed?'Expand sidebar':'Collapse sidebar');this.title=collapsed?'Expand sidebar':'Collapse sidebar'});
document.addEventListener('click',async function(event){const link=event.target.closest('a.content-editor-link');if(!link)return;event.preventDefault();const modalElement=document.getElementById('contentEditorModal'),body=document.getElementById('contentEditorBody'),modal=bootstrap.Modal.getOrCreateInstance(modalElement);body.innerHTML='<div class="text-center py-5"><div class="spinner-border text-primary"></div></div>';modal.show();try{const html=await fetch(link.href,{headers:{'X-Requested-With':'XMLHttpRequest'}}).then(r=>r.text());const doc=new DOMParser().parseFromString(html,'text/html'),card=doc.querySelector('.content-editor-card');if(!card)throw new Error('The form could not be loaded.');card.classList.remove('card');card.classList.remove('mx-auto');body.innerHTML='';body.append(...card.childNodes);modalElement.querySelector('.modal-title').textContent=body.querySelector('h1')?.textContent||'Manage content';body.querySelector('h1')?.remove()}catch(error){body.innerHTML='<div class="alert alert-danger">'+escapeHtml(error.message)+'</div>'}});
document.addEventListener('submit',async function(event){const form=event.target.closest('.content-editor-form');if(!form)return;event.preventDefault();const button=form.querySelector('[type=submit]');if(button)button.disabled=true;try{const response=await fetch(form.action,{method:'POST',body:new FormData(form),headers:{'X-Requested-With':'XMLHttpRequest','X-CSRF-Token':APP.csrf}}),data=await response.json();if(!response.ok||!data.ok)throw new Error(data.message||'Could not save.');toast(data.message,'success');bootstrap.Modal.getInstance(document.getElementById('contentEditorModal'))?.hide();setTimeout(()=>location.reload(),450)}catch(error){toast(error.message,'danger');if(button)button.disabled=false}});
document.addEventListener('click',function(event){const button=event.target.closest('.ai-generate');if(!button)return;const form=document.getElementById('aiDraftForm');form.reset();document.getElementById('aiKind').value=button.dataset.kind;const targetSelect=document.getElementById('aiTargetSelect'),targetWrap=document.getElementById('aiTargetWrap');targetSelect.innerHTML='';let options=[];try{options=JSON.parse(button.dataset.options||'[]')}catch(e){};targetWrap.classList.toggle('d-none',!options.length);options.forEach(option=>targetSelect.add(new Option(option.label,option.id)));document.getElementById('aiTargetId').value=button.dataset.target||options[0]?.id||0;targetSelect.onchange=()=>document.getElementById('aiTargetId').value=targetSelect.value;const context=document.getElementById('aiCareerContext');context.classList.toggle('d-none',!button.dataset.context);document.getElementById('aiCareerName').textContent=button.dataset.context||'';document.getElementById('aiInterestWrap').classList.toggle('d-none',button.dataset.kind!=='interest_questions');document.getElementById('aiDraftReview').classList.add('d-none');document.getElementById('aiSaveButton').classList.add('d-none');document.getElementById('aiGenerateButton').classList.remove('d-none');bootstrap.Modal.getOrCreateInstance(document.getElementById('aiDraftModal')).show()});
document.getElementById('aiDraftForm')?.addEventListener('submit',async function(event){event.preventDefault();const button=document.getElementById('aiGenerateButton');button.disabled=true;button.innerHTML='<span class="spinner-border spinner-border-sm"></span> Generating…';try{const response=await fetch(APP.base+'admin/ai_generate.php',{method:'POST',body:new FormData(this),headers:{'X-CSRF-Token':APP.csrf}}),data=await response.json();if(!response.ok||!data.ok)throw new Error(data.message||'AI is temporarily unavailable.');document.getElementById('aiDraftJson').value=data.draft_json;document.getElementById('aiDraftReview').classList.remove('d-none');document.getElementById('aiSaveButton').classList.remove('d-none')}catch(error){toast(error.message,'danger')}finally{button.disabled=false;button.innerHTML='<i class="bi bi-stars"></i> Regenerate draft'}});
document.getElementById('aiSaveButton')?.addEventListener('click',async function(){const form=document.getElementById('aiDraftForm'),body=new FormData(form);this.disabled=true;try{const response=await fetch(APP.base+'admin/ai_save_draft.php',{method:'POST',body,headers:{'X-CSRF-Token':APP.csrf}}),data=await response.json();if(!response.ok||!data.ok)throw new Error(data.message||'Could not save the draft.');toast(data.message,'success');bootstrap.Modal.getInstance(document.getElementById('aiDraftModal'))?.hide();setTimeout(()=>location.reload(),500)}catch(error){toast(error.message,'danger');this.disabled=false}});
</script></body></html>
